import hashlib


def task_func(word: str) ->str:
    pairs = []
    i = 0
    while i < len(word) - 1:
        pairs.append(word[i:i + 2])
        i += 1
    counts = {}
    for p in pairs:
        if p in counts:
            counts[p] += 1
        else:
            counts[p] = 1
    rep = '{'
    first = True
    for k in counts:
        if not first:
            rep += ', '
        rep += f"'{k}': {counts[k]}"
        first = False
    rep += '}'
    return hashlib.md5(rep.encode()).hexdigest()

import math


def task_func(s):

    if not s:
        return 0, 0.0
    tokens = [t.strip() for t in s.split(',') if t.strip()]
    numbers = []
    for token in tokens:
        try:
            numbers.append(float(token))
        except ValueError:
            continue
    count = len(numbers)
    sqrt_sum = sum(math.sqrt(n) for n in numbers)
    return count, sqrt_sum

