import logging
import pandas as pd
logger = logging.getLogger(__name__)


def task_func(l):

    try:
        values = list(l)
    except TypeError as exc:
        logger.error('Input is not iterable: %s', exc)
        raise TypeError('Input must be an iterable of numeric values') from exc
    if not values:
        logger.warning('Empty input received')
        return pd.DataFrame({'Scaled Values': []})
    try:
        min_val = min(values)
        max_val = max(values)
    except Exception as exc:
        logger.error('Failed to compute min/max: %s', exc)
        raise ValueError('Input must contain comparable numeric values'
            ) from exc
    if max_val == min_val:
        scaled = [0.0] * len(values)
    else:
        denom = max_val - min_val
        scaled = [((x - min_val) / denom) for x in values]
    return pd.DataFrame({'Scaled Values': scaled})

