import os


def task_func(values: List[Dict[str, str]], filename: str) ->str:
    if not isinstance(values, list):
        raise TypeError('Values must be a list')
    if not all(isinstance(v, dict) for v in values):
        raise TypeError('Each value must be a dictionary')
    if not filename:
        raise ValueError('Filename cannot be empty')
    wb = openpyxl.Workbook()
    sheet = wb.active
    headers = ['ID', 'Name', 'Age']
    for col_idx, header in enumerate(headers):
        sheet.cell(row=1, column=col_idx + 1).value = header
    for row_idx, row_data in enumerate(values, start=2):
        for col_idx, header in enumerate(headers):
            cell_value = row_data.get(header, '')
            sheet.cell(row=row_idx, column=col_idx + 1).value = cell_value
    path = Path(filename)
    wb.save(path)
    return os.path.abspath(path)

