import pandas as pd


def task_func(data, mapping):
    df = pd.DataFrame(data)
    for col in df.columns:
        for i in range(len(df[col])):
            if isinstance(df[col].iloc[i], str):
                words = df[col].iloc[i].split()
                new_words = []
                for word in words:
                    if word.upper() in mapping.keys():
                        new_words.append(mapping[word.upper()])
                    else:
                        new_words.append(word)
                df[col].iloc[i] = ' '.join(new_words)
    return df

