import os
import shutil
from typing import List


def task_func(directory: str, backup_directory: str) ->List[str]:

    if not os.path.isdir(directory):
        raise FileNotFoundError(
            f"Source directory '{directory}' does not exist")
    os.makedirs(backup_directory, exist_ok=True)
    copied_files = []
    for entry in os.scandir(directory):
        if entry.is_file() and entry.name.endswith('.json'):
            src_path = os.path.join(directory, entry.name)
            dst_path = os.path.join(backup_directory, entry.name)
            try:
                shutil.copy2(src_path, dst_path)
                copied_files.append(dst_path)
            except Exception as e:
                raise RuntimeError(
                    f'Failed to copy file {entry.name}: {str(e)}')
    return copied_files

