import logging
SENTENCES = ['This is a sentence', 'Another sentence here', 'More sentences']


def task_func(s: str) ->np.ndarray:
    if not isinstance(s, str):
        raise TypeError('Input must be a string')
    try:

        def clean_text(text):
            return text.lower().replace('.', '').replace(',', '').replace('!',
                '').replace('?', '')
        cleaned_input = clean_text(s)
        cleaned_sentences = [clean_text(sent) for sent in SENTENCES]
        vocab = set()
        for sent in cleaned_sentences:
            vocab.update(sent.split())
        vocab.update(cleaned_input.split())
        vocab = sorted(vocab)

        def count_words(text):
            words = text.split()
            counts = {w: (0) for w in vocab}
            for w in words:
                if w in counts:
                    counts[w] += 1
            return [counts[w] for w in vocab]

        def get_counts(text):
            words = text.split()
            counts = {w: (0) for w in vocab}
            for w in words:
                if w in counts:
                    counts[w] += 1
            return [counts[w] for w in vocab]
        vector = count_words(cleaned_input)
        return np.array(vector, dtype=int)
    except Exception:
        logging.exception('Error in task_func')
