import openpyxl
import os
from typing import List, Dict
from collections import OrderedDict
FIELDS = ['ID', 'Name', 'Age']


def task_func(values: List[OrderedDict], filename: str) ->str:

    def create_workbook():
        wb = openpyxl.Workbook()
        return wb

    def save_workbook(wb, path):
        wb.save(path)
        return os.path.abspath(path)

    def write_header(ws):
        for index, field in enumerate(FIELDS):
            ws.cell(row=1, column=index + 1).value = field

    def write_data_rows(ws, data):
        for row_num, row in enumerate(data, start=2):
            for col_num, field in enumerate(FIELDS):
                value = row.get(field, '')
                ws.cell(row=row_num, column=col_num + 1).value = value
    if not os.path.exists(os.path.dirname(filename)):
        os.makedirs(os.path.dirname(filename))
    wb = create_workbook()
    write_header(wb.active)
    write_data_rows(wb.active, values)
    return save_workbook(wb, filename)

import numpy as np
from sklearn.datasets import make_blobs
import matplotlib.pyplot as plt


def task_func(n_samples=200, centers=4, plot_path=None, random_seed=None):
    X, y = make_blobs(n_samples=n_samples, centers=centers, random_state=
        random_seed)
    distances = np.zeros((n_samples, n_samples))
    for i in range(n_samples):
        for j in range(n_samples):
            distances[i, j] = np.sqrt(np.sum((X[i] - X[j]) ** 2))
    plt.figure(figsize=(10, 8))
    scatter = plt.scatter(X[:, 0], X[:, 1], c=y)
    if plot_path:
        plt.savefig(plot_path, dpi=300, bbox_inches='tight')
        plt.close()
        return distances, None
    else:
        return distances, plt.gca()

import numpy as np
from sklearn.cluster import KMeans


def task_func(data, n_clusters=2, random_state=0):
    if not data:
        raise ValueError('Data cannot be empty')
    for point in data:
        if not isinstance(point[1], (int, float)) or not isinstance(point[2
            ], (int, float)):
            raise ValueError('Coordinates must be numeric')
    points = np.array([point[1:] for point in data])
    kmeans = KMeans(n_clusters=n_clusters, random_state=random_state)
    labels = kmeans.fit_predict(points)
    return labels

