def task_func(tuples_list: List[Tuple[float, ...]]) ->pd.DataFrame:
    try:
        if not isinstance(tuples_list, list):
            raise TypeError('tuples_list must be a list of tuples.')
        for t in tuples_list:
            if not isinstance(t, tuple):
                raise ValueError('Each element in tuples_list must be a tuple.'
                    )
            if len(t) == 0:
                warning('Empty tuple detected. It will be skipped.')
            for num in t:
                if not isinstance(num, (int, float)):
                    raise TypeError('All elements in tuples must be numeric.')
        transformed_data = []
        for t in tuples_list:
            try:
                transformed_tuple = tuple(math.sin(n) for n in t)
                transformed_data.append(transformed_tuple)
            except Exception as e:
                error(f'Error processing tuple {t}: {str(e)}')
        df = pd.DataFrame(transformed_data)
        return df
    except Exception as e:
        error(f'Main execution failed: {str(e)}')
        raise

import math
from sympy import isprime


def task_func(input_list):
    primes_set = set()
    for num in input_list:
        if isprime(num):
            primes_set.add(num)
    deg_list = []
    for p in primes_set:
        deg_list.append((math.degrees(p), p))
    n = len(deg_list)
    i = 0
    while i < n:
        j = i + 1
        while j < n:
            if deg_list[j][0] < deg_list[i][0]:
                deg_list[i], deg_list[j] = deg_list[j], deg_list[i]
            j += 1
        i += 1
    result = []
    for _, p in deg_list:
        result.append(p)
    return result

