import numpy as np
import math


class SimpleDataFrame:

    def __init__(self, data_dict):
        self._data = {k: np.array(v) for k, v in data_dict.items()}
        self.columns = list(data_dict.keys())

    def __getitem__(self, key):
        if key not in self._data:
            raise KeyError(f'Column {key!r} not found')
        return self._data[key]

    def __repr__(self):
        rows = []
        header = ' | '.join(self.columns)
        rows.append(header)
        for i in range(len(next(iter(self._data.values())))):
            row = ' | '.join(str(self._data[col][i]) for col in self.columns)
            rows.append(row)
        return '\n'.join(rows)


def task_func(data, cols):
    if not isinstance(data, list) or not all(isinstance(row, list) for row in
        data):
        raise ValueError('data must be a list of lists')
    if not isinstance(cols, list) or not all(isinstance(c, str) for c in cols):
        raise ValueError('cols must be a list of strings')
    if not data:
        raise ValueError('data cannot be empty')
    if any(len(row) != len(cols) for row in data):
        raise ValueError('Each row in data must match the length of cols')
    X = np.array(data, dtype=float)
    n_samples = X.shape[0]
    eps = 3.0
    min_samples = 2
    diff = X[:, np.newaxis, :] - X[np.newaxis, :, :]
    dist_sq = np.sum(diff ** 2, axis=2)
    neighbors = [np.where(dist_sq[i] <= eps ** 2)[0] for i in range(n_samples)]
    labels = np.full(n_samples, -1, dtype=int)
    cluster_id = 0
    visited = np.zeros(n_samples, dtype=bool)
    for i in range(n_samples):
        if visited[i]:
            continue
        visited[i] = True
        neigh = neighbors[i]
        if len(neigh) < min_samples:
            labels[i] = -1
            continue
        labels[i] = cluster_id
        seeds = list(neigh[neigh != i])
        while seeds:
            j = seeds.pop()
            if not visited[j]:
                visited[j] = True
                neigh_j = neighbors[j]
                if len(neigh_j) >= min_samples:
                    seeds.extend(neigh_j[neigh_j != j])
            if labels[j] == -1:
                labels[j] = cluster_id
            elif labels[j] == 0:
                labels[j] = cluster_id
        cluster_id += 1
    result_dict = {col: X[:, idx] for idx, col in enumerate(cols)}
    result_dict['Cluster'] = labels
    return SimpleDataFrame(result_dict)

