import re
from datetime import time


def task_func(logs):
    error_times = []
    total_time = 0
    for log in logs:
        if 'ERROR' in log:
            match = re.search('(\\d{2}):(\\d{2}):(\\d{2})', log)
            if match:
                hour, minute, second = map(int, match.groups())
                error_times.append(time(hour, minute, second))
                total_time += hour * 3600 + minute * 60 + second
    if error_times:
        avg_hour = total_time // len(error_times) // 3600
        avg_minute = total_time // len(error_times) % 3600 // 60
        avg_second = total_time // len(error_times) % 3600 % 60
        avg_time = time(avg_hour, avg_minute, avg_second)
    else:
        avg_time = time(0, 0, 0)
    return error_times, avg_time

