import os
from pathlib import Path
from collections import Counter


def task_func(directory, *args, **kwargs):
    extensions = kwargs.get('extensions', ['.txt', '.docx', '.xlsx', '.csv'])
    keep_zero = kwargs.get('keep_zero', True)
    dir_path = Path(directory)
    if not dir_path.is_dir():
        raise OSError(f'Directory {directory} does not exist.')
    target_exts = [ext.lower() for ext in extensions]
    counter = Counter()
    for file_path in dir_path.rglob('*'):
        if file_path.is_file():
            ext = file_path.suffix.lower()
            if ext in target_exts:
                counter[ext] += 1
    if keep_zero:
        for ext in target_exts:
            counter.setdefault(ext, 0)
    else:
        counter = Counter({k: v for k, v in counter.items() if v != 0})
    return counter

