import os
import re
import pandas as pd


def task_func(dir_path: str, pattern: str='^EMP'):
    regex = re.compile(pattern)
    files = {}
    for entry in os.scandir(dir_path):
        if entry.is_file() and regex.match(entry.name):
            files[entry.name] = os.path.getsize(entry.path)
    if not files:
        return pd.DataFrame(columns=['File', 'Size']).astype({'File':
            'object', 'Size': 'object'})
    sorted_names = sorted(files)
    data = {'File': sorted_names, 'Size': [files[name] for name in
        sorted_names]}
    return pd.DataFrame(data)

