import random


def task_func(l, n_groups=5):

    shuffled = l.copy()
    random.shuffle(shuffled)
    repeated = []
    for elem in shuffled:
        for _ in range(n_groups):
            repeated.append(elem)
    series_data = []
    while len(series_data) < len(repeated):
        series_data.extend(repeated[:len(repeated)])
    modified_series = []
    for elem in series_data:
        if len(elem) > n_groups:
            modified_elem = elem[n_groups:] + elem[:n_groups]
        else:
            modified_elem = elem
        modified_series.append(modified_elem)
