import json
from pathlib import Path


def task_func(directory):

    dir_path = Path(directory)
    if not dir_path.is_dir():
        raise ValueError(f"Provided path '{directory}' is not a directory.")
    result = []
    txt_files = sorted(dir_path.glob('*.txt'))
    for txt_file in txt_files:
        try:
            with txt_file.open('r', encoding='utf-8') as f:
                for line in f:
                    stripped = line.strip()
                    if not stripped:
                        continue
                    json_str = stripped.replace("'", '"')
                    try:
                        parsed = json.loads(json_str)
                    except json.JSONDecodeError:
                        raise ValueError(
                            f"Invalid dictionary representation in file '{txt_file}'."
                            )
                    if not isinstance(parsed, dict):
                        raise ValueError(
                            f"Parsed object is not a dictionary in file '{txt_file}'."
                            )
                    result.append(parsed)
        except OSError as exc:
            raise ValueError(f"Error reading file '{txt_file}': {exc}"
                ) from exc
    return result

