from collections import OrderedDict
FIELDS = ['ID', 'Name', 'Age']


def task_func(values, filename):

    logger = logging.getLogger(__name__)
    if not isinstance(values, list):
        logger.error('values must be a list')
        raise TypeError('values must be a list')
    for idx, item in enumerate(values):
        if not isinstance(item, OrderedDict):
            logger.error('Item %s is not an OrderedDict', idx)
            raise TypeError('Each item in values must be an OrderedDict')
    if not isinstance(filename, str):
        logger.error('filename must be a string')
        raise TypeError('filename must be a string')
    if not filename.lower().endswith('.xls'):
        logger.error('filename must end with .xls')
        raise ValueError('filename must end with .xls')
    abs_path = os.path.abspath(filename)
    dir_name = os.path.dirname(abs_path)
    if dir_name and not os.path.exists(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except Exception as exc:
            logger.exception('Failed to create directory %s', dir_name)
            raise
    try:
        workbook = xlsxwriter.Workbook(abs_path, {'in_memory': False})
        worksheet = workbook.add_worksheet()
        for col_idx, header in enumerate(FIELDS):
            worksheet.write(0, col_idx, header)
        for row_idx, row_data in enumerate(values, start=1):
            for col_idx, field in enumerate(FIELDS):
                value = row_data.get(field, '')
                worksheet.write(row_idx, col_idx, value)
        workbook.close()
    except Exception as exc:
        logger.exception('Error writing Excel file')
        raise
    return abs_path

