import pandas as pd
import numpy as np


def task_func(df, features):
    if not features:
        return df
    for feature in features:
        if feature in df.columns:
            min_val = df[feature].min()
            max_val = df[feature].max()
            if max_val == min_val:
                df[feature] = 0
            else:
                df[feature] = (df[feature] - min_val) / (max_val - min_val)
    return df

