def task_func(directory):
    results = []
    for filename in sorted(os.listdir(directory)):
        if not filename.endswith('.txt'):
            continue
        path = os.path.join(directory, filename)
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                stripped = line.strip()
                if not stripped:
                    continue
                try:
