                results.append(parsed)
    return results

import re
import math
from collections import Counter


def task_func(texts):
    if all(t.strip() == '' for t in texts):
        return [], []
    cleaned = [re.sub('https?://\\S+', '', t) for t in texts]
    docs_terms = [re.findall('\\b\\w+\\b', c.lower()) for c in cleaned]
    term_counts = [Counter(terms) for terms in docs_terms]
    df = {}
    for terms in docs_terms:
        for term in set(terms):
            df[term] = df.get(term, 0) + 1
    N = len(texts)
    idf = {term: (math.log((N + 1) / (df[term] + 1)) + 1) for term in df}
    features = sorted(idf)
    matrix = []
    for counts in term_counts:
        row = tuple(round(counts.get(f, 0) * idf[f], 8) for f in features)
        matrix.append(row)
    return matrix, features

import re
import math


def task_func(texts):
    cleaned = [re.sub('https?://\\S+', '', t) for t in texts]
    tokenized = [re.findall('\\b\\w+\\b', c.lower()) for c in cleaned]
    if all(len(doc) == 0 for doc in tokenized):
        return [], []
    vocab = sorted(set(word for doc in tokenized for word in doc))
    df = {}
    for w in vocab:
        count = 0
        for doc in tokenized:
            if w in doc:
                count += 1
        df[w] = count
    idf = {}
    N = len(tokenized)
    for w in vocab:
        idf[w] = math.log(N / (df[w] + 1))
    matrix = []
    for doc in tokenized:
        tf = {}
        for w in vocab:
            tf[w] = doc.count(w) / len(doc) if len(doc) > 0 else 0
        row = []
        for w in vocab:
            row.append(tf[w] * idf[w])
        matrix.append(tuple(row))
    return matrix, vocab

