import numpy as np


def task_func(s):
    words = s.split()
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    sentences = ['This is a test string.',
        "Hello! How's the test going? Good?",
        'I have 2 apples and 3 bananas.',
        'This is a really long string with many words that are repeated multiple times.'
        ]
    sentence_words = [word.split() for word in sentences]
    all_words = set()
    for sent in sentence_words:
        for w in sent:
            all_words.add(w)
    vector = np.zeros(len(all_words))
    word_list = list(all_words)
    for i, word in enumerate(word_list):
        if word in word_counts:
            vector[i] = word_counts[word]
    return vector

