import openpyxl
from pathlib import Path
from typing import List, Dict, Any
from datetime import datetime


def task_func(values: List[Dict[str, Any]], filename: str) ->str:

    def create_excel_file(values: List[Dict[str, Any]], filename: str) ->str:
        wb = openpyxl.Workbook()
        sheet = wb.active
        headers = ['ID', 'Name', 'Age']
        for col_index, col in enumerate(headers):
            sheet.cell(row=1, column=col_index + 1, value=col)
        for row_index, row_values in enumerate(values, start=2):
            for col_index, col in enumerate(headers):
                value = row_values.get(col, '')
                sheet.cell(row=row_index, column=col_index + 1, value=value)
        path = Path(filename).absolute()
        wb.save(path)
        return str(path)

    def validate_input(values: List[Dict[str, Any]], filename: str) ->bool:
        if not isinstance(values, list):
            raise TypeError('Values must be a list of dictionaries.')
        for item in values:
            if not isinstance(item, dict):
                raise TypeError('Each value must be a dictionary.')
        if not filename:
            raise ValueError('Filename cannot be empty.')
        return True
    try:
        validate_input(values, filename)
        return create_excel_file(values, filename)
    except Exception as e:
        raise RuntimeError(f'Error creating Excel file: {str(e)}')

