            raise ValueError('Sample size cannot be negative.')
        np.random.seed(seed)
        num_matches = len(matches)
        if num_matches == 0:
            return pd.DataFrame()
        if sample_size > num_matches:
            sample_size = num_matches
        sampled_indices = np.random.choice(num_matches, sample_size,
            replace=False)
        matches = matches.iloc[sampled_indices]
    return matches

