import re
from datetime import time
from typing import List, Tuple


def task_func(logs: List[str]) ->Tuple[List[time], time]:
    error_logs = [log for log in logs if 'ERROR' in log]

    def extract_time(s: str) ->int:
        match = re.search('(\\d{2}):(\\d{2}):\\d{2}', s)
        return int(match.group(1)) * 60 + int(match.group(2)
            ) if match else None
    times = []
    total_seconds = 0
    for log in error_logs:
        time_val = extract_time(log)
        if time_val is not None:
            times.append(time(*map(int, re.search('(\\d{2}):(\\d{2})', log)
                .groups())))
            total_seconds += time_val
    avg_total = total_seconds / len(times) if times else 0
    avg_h = int(avg_total // 60)
    avg_m = int(avg_total % 60)
    return times, time(avg_h, avg_m)

