import json
from datetime import datetime
import numpy as np
from decimal import Decimal


def task_func(my_obj):

    def _convert(o):
        if isinstance(o, datetime):
            return o.isoformat()
        if isinstance(o, np.ndarray):
            return o.tolist()
        if isinstance(o, Decimal):
            return str(o)
        if isinstance(o, dict):
            new_dict = {}
            for k, v in o.items():
                new_dict[k] = _convert(v)
            return new_dict
        if isinstance(o, list):
            new_list = []
            for item in o:
                new_list.append(_convert(item))
            return new_list
        if isinstance(o, tuple):
            new_tuple = []
            for item in o:
                new_tuple.append(_convert(item))
            return tuple(new_tuple)
        if isinstance(o, set):
            return list(_convert(item) for item in o)
        return o
    return json.dumps(_convert(my_obj))

