def task_func(nested_dict: Dict[str, Dict[str, float]]) ->Dict[str, float]:

    def aggregate_values(dicts_to_aggregate):
        aggregated = {}
        for d in dicts_to_aggregate:
            for key, value in d.items():
                if key == 'ele':
                    continue
                if key in aggregated:
                    aggregated[key] += value
                else:
                    aggregated[key] = value
        return aggregated

    def compute_sine(values_dict):
        return {k: math.sin(v) for k, v in values_dict.items()}
    try:
        dicts_to_aggregate = nested_dict.values()
        aggregated = aggregate_values(dicts_to_aggregate)
        result = compute_sine(aggregated)
        return result
    except AttributeError:
        raise ValueError('Invalid input: not a dictionary')
    except Exception as e:
        raise RuntimeError(f'An error occurred during processing: {e}')

