import pandas as pd


def task_func(data, mapping):
    df = pd.DataFrame(data)

    def replace_acronym(s):
        if isinstance(s, str):
            words = s.split()
            new_words = []
            for word in words:
                if word.upper() in mapping:
                    new_word = mapping[word.upper()]
                    new_words.append(new_word)
                else:
                    new_words.append(word)
            return ' '.join(new_words)
        else:
            return s
    df = df.applymap(replace_acronym)
    return df

