def task_func(directory):
    result = []
    for filename in os.listdir(directory):
        file_path = os.path.join(directory, filename)
        if not os.path.isfile(file_path):
            continue
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                try:
                    data = json.loads(content)
                    if isinstance(data, dict):
                        result.append(data)
                    else:
                        raise ValueError('Content is not a dictionary')
                except json.JSONDecodeError:
                    lines = content.split('\n')
                    for line in lines:
                        stripped_line = line.strip()
                        if stripped_line:
                            try:
                                dict_obj = ast.literal_eval(stripped_line)
                                result.append(dict_obj)
                            except (ast.InvalidLiteral, ValueError):
                                raise ValueError(
                                    'Invalid dictionary representation')
        except Exception as e:
            raise ValueError(f'Error processing file {filename}: {str(e)}')
    return result

