import os
import re
import pathlib
import pandas as pd


def task_func(dir_path: str, pattern: str='^EMP'):
    p = pathlib.Path(dir_path)
    files = [f.name for f in p.iterdir() if f.is_file()]
    matched = [f for f in sorted(files) if re.match(pattern, f)]
    if not matched:
        return pd.DataFrame(columns=['File', 'Size'])
    sizes = {f: os.path.getsize(p / f) for f in matched}
    return pd.DataFrame(list(sizes.items()), columns=['File', 'Size'])

