class SimplePlot:

    def __init__(self, x_series, y_series):
        self.x = x_series
        self.y = y_series


def task_func(df: pd.DataFrame, tuples: list, n_plots: int):
    if not isinstance(df, pd.DataFrame):
        raise TypeError('df must be a pandas DataFrame')
    if not isinstance(tuples, list):
        raise TypeError('tuples must be a list')
    if not isinstance(n_plots, int):
        raise TypeError('n_plots must be an integer')
    if n_plots < 0:
        raise ValueError('n_plots must be non-negative')
    if tuples:
        tuple_set = set(tuples)
        row_tuples = df.apply(tuple, axis=1)
        mask = row_tuples.isin(tuple_set)
        df = df[~mask].reset_index(drop=True)
    plots = []
    if not df.empty and n_plots > 0:
        cols = list(df.columns)
        for _ in range(n_plots):
            x_col, y_col = random.sample(cols, 2)
            x_series = df[x_col]
            y_series = df[y_col]
            plots.append(SimplePlot(x_series, y_series))
    return df, plots

