import base64
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding as asym_padding


def task_func(num, from_base, to_base, private_key, alphabet):
    try:
        value = int(num, from_base)
    except ValueError:
        raise ValueError('Invalid number for the given base')
    digits = tuple('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ')
    if value == 0:
        converted = '0'
    else:
        parts = []
        while value:
            value, rem = divmod(value, to_base)
            parts.append(digits[rem])
        converted = ''.join(reversed(parts))
    signature = private_key.sign(converted.encode('utf-8'), asym_padding.
        PSS(mgf=asym_padding.MGF1(hashes.SHA256()), salt_length=
        asym_padding.PSS.MAX_LENGTH), hashes.SHA256())
    return base64.b64encode(signature).decode('ascii')

