import yaml
from typing import Dict
from pathlib import Path
from dataclasses import dataclass


@dataclass
class YAMLProcessor:

    def __init__(self, file_path: str):
        self.file_path = file_path

    def load_yaml(self) ->Dict:
        try:
            with open(self.file_path, 'r') as f:
                return yaml.safe_load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f'File {self.file_path} not found')
        except yaml.YAMLError:
            raise ValueError('Invalid YAML data in file')

    def process_data(self, data: Dict, key: str) ->Dict:
        if key in data:
            data[key] = math.cos(data[key])
        return data

    def save_yaml(self, data: Dict) ->None:
        try:
            with open(self.file_path, 'w') as f:
                yaml.safe_dump(data, f)
        except PermissionError:
            raise PermissionError(
                f'Permission denied when writing to {self.file_path}')
        except yaml.YAMLError:
            raise ValueError('Error while saving YAML data')


def task_func(yaml_path: str, key: str) ->Dict:
    processor = YAMLProcessor(yaml_path)
    data = processor.load_yaml()
    modified_data = processor.process_data(data, key)
    processor.save_yaml(modified_data)
    return modified_data

