import re
from datetime import time
from typing import List, Tuple


def task_func(logs: List[str]) ->Tuple[List[time], time]:

    error_times = []
    total_seconds = 0
    for log in logs:
        if 'ERROR' in log:
            time_match = re.search('\\d{2}:\\d{2}:\\d{2}', log)
            if time_match:
                try:
                    hour, minute, second = map(int, time_match.group().
                        split(':'))
                    error_time = time(hour, minute, second)
                    error_times.append(error_time)
                    total_seconds += hour * 3600 + minute * 60 + second
                except ValueError:
                    pass
    if not error_times:
        return [], time(0, 0)
    avg_total_seconds = total_seconds / len(error_times)
    avg_hour = int(avg_total_seconds // 3600)
    avg_minute = int(avg_total_seconds % 3600 // 60)
    avg_second = int(avg_total_seconds % 3600 % 60)
