import subprocess
import os
import time
MESSAGES = {(True):
    'File generated successfully within the specified duration.', (False):
    'File not generated within the specified duration.'}


def task_func(r_script_path, output_path, duration):
    if not os.path.isfile(r_script_path):
        return False, MESSAGES[False]
    if not os.path.isdir(output_path):
        return False, MESSAGES[False]
    try:
        subprocess.call(['Rscript', r_script_path])
    except Exception:
        return False, MESSAGES[False]
    target_file = os.path.join(output_path, 'output.csv')
    start_time = time.time()
    while time.time() - start_time < duration:
        if os.path.isfile(target_file):
            return True, MESSAGES[True]
        time.sleep(0.1)
    if os.path.isfile(target_file):
        return True, MESSAGES[True]
    return False, MESSAGES[False]

