from typing import List
from pathlib import Path


def task_func(directory: str, backup_directory: str) ->List[str]:

    def create_backup_dir():
        if not os.path.exists(backup_directory):
            os.makedirs(backup_directory)

    def get_json_files():
        json_files = []
        for file in os.listdir(directory):
            path = os.path.join(directory, file)
            if os.path.isfile(path) and file.endswith('.json'):
                json_files.append(path)
        return json_files

    def copy_files(files: List[str]):
        copied_files = []
        create_backup_dir()
        for file in files:
            backup_path = os.path.join(backup_directory, os.path.basename(file)
                )
            shutil.copy2(file, backup_path)
            copied_files.append(backup_path)
        return copied_files
    if not os.path.exists(directory):
        raise FileNotFoundError(f"Directory '{directory}' does not exist")
    json_files = get_json_files()
    result = copy_files(json_files)
    return result

