import re
import math
import logging
from collections import Counter
logger = logging.getLogger(__name__)


def task_func(texts):
    if not isinstance(texts, list):
        raise TypeError('Input must be a list')
    for t in texts:
        if not isinstance(t, str):
            raise TypeError('All elements of input must be strings')
    if all(not t.strip() for t in texts):
        return [], []
    cleaned_texts = []
    for t in texts:
        try:
            cleaned = re.sub('http[s]?://\\S+', '', t)
        except re.error as e:
            logger.error(f'Regex error: {e}')
            cleaned = t
        cleaned_texts.append(cleaned)
    tokenized_docs = []
    for doc in cleaned_texts:
        tokens = re.findall('\\b\\w+\\b', doc.lower())
        tokenized_docs.append(tokens)
    vocab_set = set()
    for tokens in tokenized_docs:
        vocab_set.update(tokens)
    if not vocab_set:
        return [], []
    vocab = sorted(vocab_set)
    N = len(tokenized_docs)
    df_counts = {}
    for term in vocab:
        df = sum(1 for tokens in tokenized_docs if term in tokens)
        df_counts[term] = df
    idf = {}
    for term, df in df_counts.items():
        idf_val = math.log((N + 1) / (df + 1)) + 1
        idf[term] = idf_val
    tfidf_matrix = []
    for tokens in tokenized_docs:
        tf_counts = Counter(tokens)
        row = []
        for term in vocab:
            tf = tf_counts.get(term, 0)
            tfidf_val = tf * idf[term]
            row.append(round(tfidf_val, 8))
        tfidf_matrix.append(tuple(row))
    return tfidf_matrix, vocab

