import pandas as pd
import re


def task_func(data, mapping):
    df = pd.DataFrame(data)

    def replace_acronyms(text, mapping):
        parts = re.split('(\\b[A-Z]+\\b)', text)
        return ''.join(mapping.get(part, part) for part in parts)

    def repl(x):
        return replace_acronyms(x, mapping) if isinstance(x, str) else x
    return df.apply(lambda col: col.apply(repl))

