import os
from collections import defaultdict


def task_func(directory, extensions=None, keep_zero=True):

    if extensions is None:
        extensions = ['.txt', '.docx', '.xlsx', '.csv']
    file_counts = defaultdict(int)
    if not os.path.exists(directory):
        raise OSError('Directory does not exist')
    for root, _, files in os.walk(directory):
        for file in files:
            ext = os.path.splitext(file)[1]
            if ext.lower() in [e.lower() for e in extensions]:
                file_counts[ext] += 1
    if keep_zero:
        for ext in extensions:
            if ext not in file_counts:
                file_counts[ext] = 0
    return Counter(file_counts)

import math
from sympy import isprime


def task_func(input_list):

    def filter_primes(lst):
        return [i for i in lst if isprime(i)]

    def sort_primes(primes):
        primes.sort(key=lambda x: (math.degrees(math.atan(x)), x))
        return primes

    def get_prime_degrees(primes):
        return [(i, math.degrees(math.atan(i))) for i in primes]

    def merge_and_sort(degrees):
        merged = {}
        for num, degree in degrees:
            if num not in merged or degree < merged[num][1]:
                merged[num] = degree, num
        return [num for num, _ in sorted(merged.items(), key=lambda x: x[1])]
    primes = filter_primes(input_list)
    degrees = get_prime_degrees(primes)
    result = merge_and_sort(degrees)
    return result

import math
from sympy import isprime


def task_func(input_list):

    def rad_to_deg(x):
        return math.degrees(x)

    def rad_to_deg_copy(x):
        return math.degrees(x)
    prime_candidates = set()
    for val in input_list:
        if isprime(val):
            prime_candidates.add(val)
    degree_lookup = {}
    for prime in prime_candidates:
        degree_lookup[prime] = rad_to_deg(prime)
    sorted_primes = sorted(prime_candidates, key=lambda num: (degree_lookup
        [num], num))
    return sorted_primes

