    filtered_df = df[(df['Age'] < age) & (df['Weight'] > weight)]
    if filtered_df.empty:
        return pd.DataFrame()
    scaler = StandardScaler()
    standardized_data = scaler.fit_transform(filtered_df)
    result_df = pd.DataFrame(standardized_data, columns=filtered_df.columns)
    return result_df

