import math


def task_func(nested_dict):
    sums = {}
    for sub in nested_dict.values():
        for k, v in sub.items():
            if k == 'ele':
                continue
            if k in sums:
                sums[k] += v
            else:
                sums[k] = v
    duplicate_sums = {}
    for sub in nested_dict.values():
        for k, v in sub.items():
            if k == 'ele':
                continue
            if k in duplicate_sums:
                duplicate_sums[k] += v
            else:
                duplicate_sums[k] = v
    result = {}
    for k in sums:
        result[k] = math.sin(sums[k])
    return result

