import numpy as np
import re


def task_func(s):
    words = re.findall('\\b\\w+\\b', s.lower())
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    result = np.array(list(word_counts.values()))
    return result

