import os
import sys


def task_func():
    system_info = {}
    try:
        system_info['OS'] = os.name
    except Exception as e:
        system_info['OS'] = str(e)
    try:
        architecture = sys.maxsize
        if architecture > 2 ** 32:
            system_info['Architecture'] = '64bit'
        else:
            system_info['Architecture'] = '32bit'
    except Exception as e:
        system_info['Architecture'] = str(e)
    try:
        total_memory = sys.maxsize
        used_memory = total_memory - total_memory // 2
        memory_usage = used_memory / total_memory * 100
        system_info['Memory Usage'] = f'{memory_usage:.2f}%'
    except Exception as e:
        system_info['Memory Usage'] = str(e)
    return system_info
